      "title": "RAG-style retrieve",
      "lang": "js",
      "desc": "Fake top-1 by keyword for practice.",
      "code": "function retrieve(q, chunks) {\n  return chunks.find((c) => c.includes(q.slice(0, 4))) || chunks[0];\n}"
